return ['domain'=>NULL,'plural-forms'=>'nplurals=1; plural=0;','language'=>'tt_RU','project-id-version'=>'Babilim 1.2.0','pot-creation-date'=>'2026-11-05T19:51:13+00:00','po-revision-date'=>'2026-11-05T19:51:13+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Сайтыгызда инде урнаштырылган плагиннар һәм темалар өчен житмәгән тәрҗемәләрне өсти.','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'Бу йөкләү экраны искергән: аннан соң башка йөкләү әзерләнгән. Берни дә җибәрелмәде. Хәзерге йөкләүне Тәрҗемәләр исемлегеннән карап чыгыгыз.','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'Бушлай хезмәт планы һәр сайтка плагиннар һәм темалар өчен чикләнгән санда урыннар бирә; кулланылган урыннар Babilim\'ны кабызгач, Көйләүләрдә күрсәтелә.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Тәрҗемә соравы бу плагинны яки теманы шушы сайт өчен бушлай хезмәт планының урыннарының берсенә урнаштыра (чик: темалар өчен %1$d, плагиннар өчен %2$d), әгәр аның урыны инде булмаса. Урын кулланылган булып кала, һәм уңышсыз тәрҗемә аны бушатмый.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Тәрҗемә соравы бу плагинны яки теманы шушы сайт өчен бушлай хезмәт планының урыннарының берсенә урнаштыра, әгәр аның урыны инде булмаса. Урын кулланылган булып кала, һәм уңышсыз тәрҗемә аны бушатмый.','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one (the limit is %1$d for themes and %2$d for plugins). A slot stays used, and a failed translation does not free it. Continue?'=>'Әгәр бу плагин яки тема шушы сайт өчен бушлай хезмәт планының урыннарында әле булмаса, тәрҗемә соравы аны шундый урынга урнаштыра (чик: темалар өчен %1$d, плагиннар өчен %2$d). Урын кулланылган булып кала, һәм уңышсыз тәрҗемә аны бушатмый. Дәвам итәргәме?','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one. A slot stays used, and a failed translation does not free it. Continue?'=>'Әгәр бу плагин яки тема шушы сайт өчен бушлай хезмәт планының урыннарында әле булмаса, тәрҗемә соравы аны шундый урынга урнаштыра. Урын кулланылган булып кала, һәм уңышсыз тәрҗемә аны бушатмый. Дәвам итәргәме?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Бу челтәрдәге %1$d сайт плагин бетерелгәндә үзенең Babilim идентификаторын юкка чыгарырга көйләнгән. Шуннан соң әлеге сайтларга беркетелгән түләүле лицензияне автоматик рәвештә торгызып булмаячак; Babilim ярдәменә %2$s адресы буенча мөрәҗәгать итәргә кирәк булачак. Идентификаторларны саклау өчен «Кире алу» төймәсенә басыгыз, әлеге сайтларның һәрберсенең Babilim көйләүләрендә «Бетергәндә Babilim\'ның барлык мәгълүматларын бетерергә» билгесен алыгыз һәм кабат сүндерегез. Барыбер сүндерергәме?','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s эшлисе берни юк.','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Телне сайлагыз.','%d failed'=>'%d уңышсыз','%d not yet tried'=>'%d әле сынап каралмаган','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'%d хисап көтә. "Һәрвакыт уртаклашу" һәм "Уртаклашмау" аларның барысына да кагыла.','%d skipped'=>'%d калдырылды','%d succeeded'=>'%d уңышлы','%d to install'=>'%d урнаштырырга','(a public key generated for this site)'=>'(бу сайт өчен җитештерелгән ачык ачкыч)','(detected)'=>'(табылган)','(generic codes and coordinates only)'=>'(бары тик гомуми кодлар һәм координатлар)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Чистарту %1$s вакытында туктатылды: %2$s. Берни дә бетерелмәде.','A file in the component could not be read, so it was not packaged.'=>'Компоненттагы бер файлны укып булмады, шуңа күрә ул пакетланмады.','A host that serves only one PHP request at a time cannot complete this step.'=>'Бер үк вакытта бары тик бер PHP соравын гына эшкәртә торган хостинг бу адымны үти алмый.','A part of the upload kept failing, so the upload was cancelled.'=>'Йөкләүнең бер өлеше берничә тапкыр уңышсыз тәмамланды, шуңа күрә йөкләү туктатылды.','A translation cannot be requested for that locale on this site right now.'=>'Хәзерге вакытта бу сайтта ул локаль өчен тәрҗемә соратып булмый.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Тәрҗемәләр индексына язу %1$s вакытында (%2$s) башка сорау белән каршылыкка керде һәм кулланылмады; иң соңгы версия саклап калынды.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Тәрҗемә индексына %1$s вакытында (%2$s) язу тәмамлана алмады һәм кулланылмады (%3$s).','Account'=>'Хисап язмасы','Add another language'=>'Тагын бер тел өстәү','Advanced'=>'Өстәмә','All'=>'Барысы','All free-plan slots for this site are used'=>'Бу сайт өчен бушлай план урыннарының барысы да кулланыла','All languages'=>'Барлык телләр','Already in WordPress core'=>'Инде WordPress үзәгендә бар','Already installed.'=>'Инде урнаштырылган.','Always share'=>'Һәрвакыт уртаклашу','Another installation is running; try again in a moment.'=>'Башка урнаштыру бара; бераздан кабат сынап карагыз.','Automatic installs'=>'Автоматик урнаштырулар','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Автоматик урнаштырулар хәзер сүндерелгән; кирәк булса, көйләүләрдә аларны кабат кабызыгыз.','Available'=>'Бар','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Булган тәрҗемәләрне бер басу белән урнаштырырга, ә житмәгәннәрен соратырга мөмкин. Автоматик урнаштырулар кабызылганда, хезмәт сез идарә иткән телләр өчен булган дип күрсәткән тәрҗемәләр көненә ике тапкыр синхронлаштыру вакытында урнаштырыла.','Available · %s'=>'Бар · %s','Babilim Settings'=>'Babilim көйләүләре','Babilim adds translations for every language checked here.'=>'Babilim монда билгеләнгән һәр тел өчен тәрҗемәләр өсти.','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim сайттан читтәге вакытлыча папканы раслый алмады, шуңа компонент пакетланмады һәм берни дә йөкләнмәде. wp-config.php файлында BABILIM_TEMP_DIR\'ны web root тыш язу мөмкин булган папка итеп билгеләгез (мәсәлән, сайтыгызның ачык папкасы эчендә түгел, ә аның янындагы папка), яки хостингтан аны сорагыз.','Babilim could not finish checking this site.'=>'Babilim бу сайтны тикшереп бетерә алмады.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim кабызуны тәмамлый алмады (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim бу сайтны тикшереп бетерә алмады (хезмәт сайт белән кире элемтә урнаштыра алмады). Теркәү вакытлыча туктатылды.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim бу сайтны раслый алмады, шуңа күрә раслау уңышлы булганчы берни дә йөкләнми һәм урнаштырылмый.','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim бу сайтны раслый алмады, шуңа күрә бернәрсә дә йөкләнмәде һәм урнаштырылмады.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim бу сайттагы сезнең телгә тәрҗемәсе булмаган плагиннарны һәм темаларны таба һәм аларның һәрберсе өчен тәрҗемә урнаштыра.','Babilim has not been enabled for this site yet.'=>'Babilim бу сайт өчен әле кабызылмаган.','Babilim has not installed any translation for this language.'=>'Babilim бу тел өчен бер тәрҗемә дә урнаштырмады.','Babilim hit an error. Share an error report?'=>'Babilim\'да хата килеп чыкты. Хата турындагы хисапны уртаклашасызмы?','Babilim installed %d translation automatically since your last visit.'=>'Соңгы керүегездән бирле Babilim %d тәрҗемәне автоматик урнаштырды.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim сүндерелгән. Башка бернәрсә дә җибәрелми; урнаштырылган тәрҗемәләр эшләвен дәвам итә.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim кабызылган: бу сайт расланган һәм %d компонент табылды.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim бу сайтны кабыза һәм тикшерә… (соңгы омтылыш: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim бу сайтны кабыза һәм тикшерә… Бу битне яңартыгыз яки планлаштырылган тикшерүнең тәмамлануын көтегез.','Babilim is not enabled.'=>'Babilim кабызылмаган.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim плагин бетерелгәндә бу сайтның идентификаторын юкка чыгарырга көйләнгән. Шуннан соң бу сайтка беркетелгән түләүле лицензияне автоматик рәвештә торгызып булмас иде; Babilim ярдәменә %s адресы буенча мөрәҗәгать итәргә кирәк булачак. Идентификаторны саклау өчен «Кире алу» төймәсенә басыгыз, Babilim көйләүләрендә «Бетергәндә Babilim\'ның барлык мәгълүматларын бетерергә» билгесен алыгыз һәм кабат сүндерегез. Барыбер сүндерергәме?','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim өчен бу адымга бирелгән вакыт бетте; ул киләсе тикшерүдә дәвам итәчәк.','Babilim settings'=>'Babilim көйләүләре','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Babilim синхронлаштыруы хезмәт тарафыннан вакытлыча тоткарлана (сорау чикләнгән); %s узгач яңадан сынап карар.','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'Бу йөкләү көткән вакытта Babilim яңартылды. Иске пакет бетерелде; йөкләүне янадан раслагыз.','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim %1$s (версия %2$s) файлларын йөкләячәк: һәр .php һәм .js файлын, һәр block.json файлын һәм аның төп папкасындагы readme.txt, readme.md, style.css һәм theme.json файлларын. Алар тәрҗемә ителәсе тексны табу һәм плагинны яки теманы билгеләү өчен кулланыла.','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest кулланып булмый: %s','Back'=>'Кире','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Элек бу домен өчен лицензия алган идегезме? Түләгәндә алган торгызу кодын кертегез.','Broken placeholder'=>'Боzылган урын тутыргыч','Build'=>'Җыелма версиясе','Built'=>'Төзелгән','Bulk actions apply only to the selected language of each selected component.'=>'Күпләп гамәлләр сайланган һәр компонентның сайланган теленә генә кагыла.','Bulk actions apply to every matching language of each selected component.'=>'Күпләп гамәлләр сайланган һәр компонентның барлык туры килгән телләренә кагыла.','Bulk download:'=>'Күпләп йөкләп алу:','Bulk request:'=>'Күпләп сорату:','Bulk update:'=>'Күпләп яңарту:','Bundled with the plugin'=>'Плагин белән бергә килә','Bundled with the theme'=>'Тема белән бергә килә','By clicking Enable, you agree to send the information listed above to Babilim.'=>'"Кабызу" төймәсенә басып, сез өстә күрсәтелгән мәгълүматны Babilim\'га җибәрүгә ризалашасыз.','By continuing you confirm that you have the right to upload this component.'=>'Дәвам итеп, сез бу компонентны йөкләүгә хокукыгыз барлыгын раслыйсыз.','Cancel'=>'Баш тарту','Category'=>'Категория','Check again'=>'Кабат тикшерү','Check again now'=>'Хәзер кабат тикшерү','Checkout is not available for this site right now.'=>'Хәзер бу сайт өчен түләү мөмкин түгел.','Choose'=>'Сайлау','Choose a category…'=>'Категорияне сайлагыз…','Choose a language'=>'Телне сайлагыз','Choose a language…'=>'Тел сайлагыз…','Clear filters'=>'Сөзгечләрне чистарту','Close'=>'Ябу','Component'=>'Компонент','Confirm'=>'Раслау','Conflicting keys'=>'Каршылыклы ачкычлар','Continue'=>'Дәвам итү','Continue next batch (%d left)'=>'Киләсе төркемне дәвам итү (%d калды)','Continuing…'=>'Дәвам ителә…','Could not back up %s before replacing it.'=>'%s файлын алыштырганчы резерв күчермә ясап булмады.','Could not create the package archive.'=>'Пакет архивын булдырып булмады.','Could not determine active components; the existing merged index was left unchanged.'=>'Актив компонентларны билгеләп булмады; булган берләштерелгән индекс үзгәрешсез калдырылды.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Урнаштырылган плагиннарны/темаларны билгеләп булмады; тикшерү төшереп калдырылды, бернәрсә дә бетерелмәде.','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Сервистан WordPress.org телләренең тулы исемлеген йөкләп булмады, шуңа күрә хәзер башка тел өстәп булмый.','Could not move %s into place.'=>'%s файлын урынына күчереп булмады.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'\'%s\' өчен берләштерелгән индексны урынына күчереп булмады; алдагы хезмәт күрсәтелгән индекс (булса) ярым яңартылган килеш калдырылмыйча бетерелде. Киләсе уңышлы яңадан төзүгә кадәр бу локаль өчен default-домен өстәмәсе бирелми.','Could not open zip: %s'=>'Zip-ны ачып булмады: %s','Could not prepare %s for rollback.'=>'%s файлын кире кайтару өчен әзерләп булмады.','Could not read %s back after moving it into place.'=>'%s файлын урынына күчергәннән соң кире укып булмады.','Could not read: %s'=>'Укып булмады: %s','Could not restore the purchase: %s'=>'Сатып алуны торгызып булмады: %s','Could not show a new restore code: %s'=>'Яңа торгызу кодын күрсәтеп булмады: %s','Could not stage %s'=>'%s әзерләнмәде','Could not stage default/%s'=>'default/%s әзерләнмәде','Could not start checkout: %s'=>'Түләүне башлап булмады: %s','Could not verify entry count for %s'=>'%s өчен язмалар санын тикшереп булмады','Could not write the downloaded package to disk.'=>'Йөкләнгән пакетны дискка язып булмады.','Could not write the staged merged index.'=>'Әзерләнгән берләштерелгән индексны язып булмады.','Current translation'=>'Хәзерге тәрҗемә','Custom overrides'=>'Үзем билгеләгән тәрҗемә алмаштырулары','Danger zone'=>'Куркыныч зона','Default supplement entry count mismatch.'=>'Default өстәмәсендәге язмалар саны туры килми.','Delete all Babilim data on uninstall'=>'Бетергәндә Babilim\'ның барлык мәгълүматларын бетерергә','Disable Babilim'=>'Babilim\'ны сүндерергә','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Babilim\'ны сүндерергәме? Урнаштырылган тәрҗемәләр саклана, ләкин башка тикшерүләр һәм йөкләүләр башкарылмый.','Don\'t share'=>'Уртаклашмау','Download'=>'Йөкләп алу','Downloaded and installed.'=>'Йөкләнде һәм урнаштырылды.','Downloading…'=>'Йөкләп алына…','Downloads: %1$d/%2$d (%3$s)'=>'Йөкләүләр: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Һәр компонентның һәр телнең уртак default-домен өстәмәсенә кертәчәк өлеше.','Enable Babilim'=>'Babilim\'ны кабызу','Enabling…'=>'Кабызыла…','English (United States)'=>'Инглиз теле (АКШ)','Entries'=>'Язмалар','Entry count mismatch for %s'=>'%s өчен язмалар саны туры килми','Error reports'=>'Хата турындагы хисаплар','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'Урнаштырылган һәр плагин/тема: аның slug-ы, версиясе, текст домен(нар)ы, ул wp.org исемлегендәме, үзенең кертелгән локальләре һәм Babilim тәрҗемәсен инде урнаштырган локальләрегез.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Бу сайтта кулланылган һәр локаль (сайт локале, урнаштырылган тел пакетлары, кулланучылар локальләре һәм кул белән өстәлгәннәре). Һичбер локаль башкасыннан аерым каралмый.','Excluded'=>'Чыгарылган','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'Башка исемле яки киңәйтмәле файллар кертелми, шулай ук uploads, cache, logs, backup, data, vendor, node_modules һәм languages папкалары, яшерен файллар һәм исемнәре киң таралган серле файлларга туры килгән файллар (wp-config*, .env*, *.sql, *.log, *.pem, *.key) да кертелми. Код файлларында барыбер уртаклашасыгыз килмәгән текст яки мәгълүмат булырга мөмкин; ышанмасагыз, аларны тикшерегез. Файллар хезмәткә барып житкәч, хезмәт шундый ук төр файлларны яңадан бетерә.','Free'=>'Түләүсез','Free-plan slots'=>'Бушлай план урыннары','General'=>'Гомуми','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Әгәр бу көйләү кабызылган булса, плагинны бетергәндә сайтның идентификаторы да юкка чыгарыла. Шуннан соң бу сайтка беркетелгән түләүле лицензияне автоматик рәвештә торгызып булмый; аны кире алу өчен Babilim ярдәменә %s адресы буенча мөрәҗәгать итәргә кирәк булачак.','Included'=>'Кертелгән','Included in index'=>'Индекска кертелгән','Install available translations automatically'=>'Булган тәрҗемәләрне автоматик рәвештә урнаштырырга','Installed'=>'Урнаштырылган','Installed translations are kept, but no further checks or downloads will run.'=>'Урнаштырылган тәрҗемәләр саклана, ләкин башка тикшерүләр һәм йөкләүләр башкарылмый.','Installed · %s'=>'Урнаштырылган · %s','Installed · built for %1$s, this site has %2$s'=>'Урнаштырылган · %1$s өчен төзелгән, бу сайтта %2$s','Installed · built for %s'=>'Урнаштырылган · %s өчен төзелгән','Installed · built for %s, all free-plan slots for this site are used'=>'Урнаштырылган · %s өчен төзелгән, бу сайт өчен бушлай план урыннарының барысы да кулланыла','Installed · built for %s, new version failed'=>'Урнаштырылган · %s өчен төзелгән, яңа версия уңышсыз булды','Installed · built for %s, new version not covered by the free service plan'=>'Урнаштырылган · %s өчен төзелгән, яңа версия бушлай хезмәт планына кермәгән','Installed · built for %s, new version scheduled'=>'Урнаштырылган · %s өчен төзелгән, яңа версия планлаштырылды','Installed · built for %s, translating the new version…'=>'Урнаштырылган · %s өчен төзелгән, яңа версия тәрҗемә ителә…','Installed · built for a different version'=>'Урнаштырылган · башка версия өчен төзелгән','Installed · built for a different version, all free-plan slots for this site are used'=>'Урнаштырылган · башка версия өчен төзелгән, бу сайт өчен бушлай план урыннарының барысы да кулланыла','Installed · built for a different version, new version failed'=>'Урнаштырылган · башка версия өчен төзелгән, яңа версия уңышсыз булды','Installed · built for a different version, new version not covered by the free service plan'=>'Урнаштырылган · башка версия өчен төзелгән, яңа версия бушлай хезмәт планына кермәгән','Installed · built for a different version, new version scheduled'=>'Урнаштырылган · башка версия өчен төзелгән, яңа версия планлаштырылды','Installed · built for a different version, translating the new version…'=>'Урнаштырылган · башка версия өчен төзелгән, яңа версия тәрҗемә ителә…','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Ул сервисның хостинг провайдеры тарафыннан саклана һәм тәрҗемә әзерләү өчен AI моделләре белән эшкәртелә.','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Барысын да чистартканда яки бу плагинны бетергәндә үзем билгеләгән тәрҗемә алмаштыруларын саклап калырга.','Language'=>'Тел','Language:'=>'Тел:','Languages'=>'Телләр','Languages found on this site: %s.'=>'Бу сай